// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Module-level font loading — delayRender/continueRender handled internally
const { fontFamily } = loadInter();



export type CartoonCalendarProps = Record<string, any>;

const TearOffPage: React.FC<{
  word: string;
  index: number;
  tearFrame: number;
  fps: number;
  calWidth: number;
  calHeight: number;
  pageColor: string;
  textColor: string;
}> = ({
  word,
  index,
  tearFrame,
  calWidth,
  calHeight,
  pageColor,
  textColor,
}) => {
  const frame = useCurrentFrame();
  const timeSinceTear = Math.max(0, frame - tearFrame);

  // Gravity fall physics: d = 0.5 * a * t^2
  const fallY = 0.5 * 3.5 * timeSinceTear ** 2;

  // Swing and drift mechanics
  const dir = index % 2 === 0 ? 1 : -1;
  const driftX = timeSinceTear * 10 * dir;
  const rotZ = timeSinceTear * 0.6 * dir;

  const isActive = frame >= tearFrame;
  const currentY = isActive ? fallY : 0;
  const currentX = isActive ? driftX : 0;
  const currentRot = isActive ? rotZ : 0;

  // Split lines to handle explicit line breaks (like \n)
  const lines = word.split(/\r?\n|\\n/);
  const maxLineLength = Math.max(...lines.map((l) => l.length), 1);

  // Dynamic font sizing heuristic to fit words horizontally, slightly smaller than before
  const giantFontSize = Math.min(160, (calWidth * 0.8) / (maxLineLength * 0.65));

  return (
    <div
      style={{
        position: "absolute",
        top: 0,
        left: 0,
        width: calWidth,
        height: calHeight,
        backgroundColor: pageColor,
        border: "8px solid #000",
        borderRadius: "24px",
        boxShadow: isActive ? "0px 20px 30px rgba(0,0,0,0.2)" : "none",
        transform: `translate(${currentX}px, ${currentY}px) rotate(${currentRot}deg)`,
        transformOrigin: "top center",
        zIndex: 100 - index,
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        paddingTop: calHeight * 0.2, // Space for the red header
        paddingBottom: 40,
        paddingLeft: 40,
        paddingRight: 40,
        willChange: "transform",
      }}
    >
      <div
        style={{
          flex: 1,
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
          width: "100%",
          gap: "8px",
        }}
      >
        {lines.map((line, i) => (
          <span
            key={i}
            style={{
              fontSize: giantFontSize,
              color: textColor,
              textTransform: "uppercase",
              fontWeight: index === 0 ? 900 : 700, // Make the first page specifically bolder
              lineHeight: 1.1,
              textAlign: "center",
              textShadow: "4px 4px 0px rgba(0,0,0,0.1)", // Slight cartoon depth
            }}
          >
            {line}
          </span>
        ))}
      </div>
    </div>
  );
};

const CartoonCalendar: React.FC<CartoonCalendarProps> = ({
  backgroundColor = "#7bed9f",
  transparentBackground = false,
  durationInSeconds = 7, // Bumped slightly to account for the extra word
  words = ["Compliance\nBreaches", "Months", "after", "they", "happen"],
  headerColor = "#ff4757",
  pageColor = "#ffffff",
  textColor = "#2f3542",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Dimensions optimized for potential 9:16 vertical usage
  const calWidth = width * 0.8; 
  const calHeight = calWidth * 1.1; 
  const headerHeight = calHeight * 0.2; 

  // Animation Timing calculations
  const totalFrames = durationInSeconds * fps;
  const startDelay = 30; // 1s hold on first page
  const endHold = 45; // 1.5s hold on final page
  const availableFrames = Math.max(1, totalFrames - startDelay - endHold);
  
  const numTears = Math.max(0, words.length - 1);
  const tearInterval = numTears > 0 ? availableFrames / numTears : 0;

  // Entrance Bounce
  const entranceScale = spring({
    fps,
    frame,
    config: { damping: 12, stiffness: 90 },
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          position: "relative",
          width: calWidth,
          height: calHeight,
          transform: `scale(${entranceScale}) rotate(-2deg)`,
        }}
      >
        {/* Calendar Backboard (visible as pages fall away) */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: calWidth,
            height: calHeight,
            backgroundColor: "#f1f2f6", // Slightly off-white to distinguish from pages
            border: "8px solid #000",
            borderRadius: "24px",
            boxShadow: "16px 16px 0px 0px rgba(0,0,0,1)",
            zIndex: 10,
          }}
        />

        {/* The Pages */}
        {words.map((word, i) => {
          const isLastPage = i === words.length - 1;
          const tearFrame = isLastPage
            ? Infinity
            : startDelay + i * tearInterval;

          return (
            <TearOffPage
              key={i}
              index={i}
              word={word}
              tearFrame={tearFrame}
              fps={fps}
              calWidth={calWidth}
              calHeight={calHeight}
              pageColor={pageColor}
              textColor={textColor}
            />
          );
        })}

        {/* Red Header */}
        <div
          style={{
            position: "absolute",
            top: 0,
            left: 0,
            width: calWidth,
            height: headerHeight,
            backgroundColor: headerColor,
            border: "8px solid #000",
            borderRadius: "24px 24px 0 0",
            borderBottom: "8px solid #000",
            zIndex: 200,
            boxShadow: "0px 12px 0px 0px rgba(0,0,0,0.1) inset", // Cartoon highlight
          }}
        />

        {/* Binding Rings */}
        <div
          style={{
            position: "absolute",
            top: -40,
            left: 0,
            width: calWidth,
            height: 80,
            zIndex: 250,
            display: "flex",
            justifyContent: "space-evenly",
            alignItems: "center",
            padding: "0 60px",
          }}
        >
          {[1, 2, 3, 4, 5].map((i) => (
            <div
              key={i}
              style={{
                width: 36,
                height: 80,
                backgroundColor: "#dfe4ea",
                border: "6px solid #000",
                borderRadius: "18px",
                boxShadow: "4px 4px 0px 0px #000",
              }}
            />
          ))}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default CartoonCalendar;